import java.io.*;
import java.net.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import java.security.MessageDigest;
import java.nio.charset.StandardCharsets;

public class SecureVaultServer {
    private static final int PORT = 8443;
    private static final int MAX_REQUESTS_PER_WINDOW = 100;
    private static final int WINDOW_SIZE_MS = 60000;
    private static final Map<String, UserSession> sessions = new ConcurrentHashMap<>();
    private static final Map<String, String> vaultStore = new ConcurrentHashMap<>();
    private static final Map<String, RateLimitEntry> rateLimits = new ConcurrentHashMap<>();

    static class RateLimitEntry {
        private int requestCount;
        private int windowStartTime; // milliseconds since epoch truncated to int
        private final Object lock = new Object();

        RateLimitEntry() {
            this.requestCount = 0;
            this.windowStartTime = (int)(System.currentTimeMillis() & 0x7FFFFFFF);
        }

        // Returns true if request is allowed under rate limit
        boolean allowRequest() {
            synchronized(lock) {
                int currentTime = (int)(System.currentTimeMillis() & 0x7FFFFFFF);
                int elapsed = currentTime - windowStartTime;

                // If window has expired, reset
                if (elapsed >= WINDOW_SIZE_MS || elapsed < 0) {
                    windowStartTime = currentTime;
                    requestCount = 1;
                    return true;
                }

                requestCount++;
                return requestCount <= MAX_REQUESTS_PER_WINDOW;
            }
        }
    }

    static class UserSession {
        final String username;
        final String role;
        final long createdAt;
        private int accessCredits; // tracks remaining privileged operations
        private int lastOperationTime;

        UserSession(String username, String role) {
            this.username = username;
            this.role = role;
            this.createdAt = System.currentTimeMillis();
            this.accessCredits = 50;
            this.lastOperationTime = (int)(System.currentTimeMillis() % Integer.MAX_VALUE);
        }

        // Calculate available credits based on time elapsed and base credits
        // Credits regenerate over time: 1 credit per second elapsed
        int getAvailableCredits() {
            int now = (int)(System.currentTimeMillis() % Integer.MAX_VALUE);
            int timeDelta = now - lastOperationTime; // can overflow!
            int regenerated = timeDelta / 1000; // credits regenerated
            return accessCredits + regenerated;
        }

        void consumeCredit() {
            int now = (int)(System.currentTimeMillis() % Integer.MAX_VALUE);
            int timeDelta = now - lastOperationTime;
            int regenerated = timeDelta / 1000;
            accessCredits = Math.min(50, accessCredits + regenerated) - 1;
            lastOperationTime = now;
        }

        boolean isAdmin() {
            return "admin".equals(role);
        }
    }

    public static void main(String[] args) throws Exception {
        // Pre-populate vault with sensitive data
        vaultStore.put("secret/api-key", "sk-prod-a8f3b2c1d4e5f6789");
        vaultStore.put("secret/db-password", "postgres://admin:Sup3rS3cr3t@db.internal:5432");
        vaultStore.put("secret/encryption-key", "AES256:k3y-m4t3r14l-d0-n0t-3xp0s3");
        vaultStore.put("config/app-name", "VaultServer v2.1");
        vaultStore.put("config/max-connections", "500");

        ServerSocket server = new ServerSocket(PORT);
        System.out.println("SecureVaultServer listening on port " + PORT);

        ExecutorService pool = Executors.newFixedThreadPool(8);
        while (true) {
            Socket client = server.accept();
            pool.submit(() -> handleClient(client));
        }
    }

    static void handleClient(Socket client) {
        try (BufferedReader in = new BufferedReader(new InputStreamReader(client.getInputStream()));
             PrintWriter out = new PrintWriter(client.getOutputStream(), true)) {

            String requestLine = in.readLine();
            if (requestLine == null) return;

            Map<String, String> headers = new HashMap<>();
            String line;
            while ((line = in.readLine()) != null && !line.isEmpty()) {
                int colon = line.indexOf(':');
                if (colon > 0) {
                    headers.put(line.substring(0, colon).trim().toLowerCase(),
                               line.substring(colon + 1).trim());
                }
            }

            String[] parts = requestLine.split(" ");
            if (parts.length < 2) { sendError(out, 400, "Bad Request"); return; }

            String method = parts[0];
            String path = parts[1];
            String clientIp = client.getInetAddress().getHostAddress();

            // Rate limiting check
            RateLimitEntry rateEntry = rateLimits.computeIfAbsent(clientIp, k -> new RateLimitEntry());
            if (!rateEntry.allowRequest()) {
                sendError(out, 429, "Rate limit exceeded");
                return;
            }

            // Route handling
            if (path.equals("/auth") && method.equals("POST")) {
                handleAuth(in, out, headers);
            } else if (path.startsWith("/vault/")) {
                handleVaultAccess(out, path, headers);
            } else if (path.equals("/health")) {
                sendResponse(out, 200, "{\"status\":\"healthy\"}");
            } else {
                sendError(out, 404, "Not Found");
            }

        } catch (IOException e) {
            // Connection error, ignore
        }
    }

    static void handleAuth(BufferedReader in, PrintWriter out, Map<String, String> headers) throws IOException {
        int contentLength = Integer.parseInt(headers.getOrDefault("content-length", "0"));
        char[] body = new char[contentLength];
        in.read(body, 0, contentLength);
        String bodyStr = new String(body);

        // Parse simple form: username=X&password=Y
        Map<String, String> params = parseFormBody(bodyStr);
        String username = params.getOrDefault("username", "");
        String password = params.getOrDefault("password", "");

        // Validate credentials (simplified - in production use bcrypt)
        if (!isValidCredential(username, password)) {
            sendError(out, 401, "Invalid credentials");
            return;
        }

        String role = username.equals("admin") ? "admin" : "user";
        String sessionId = generateSessionId(username);
        sessions.put(sessionId, new UserSession(username, role));

        sendResponse(out, 200, "{\"session_id\":\"" + sessionId + "\",\"role\":\"" + role + "\"}");
    }

    static void handleVaultAccess(PrintWriter out, String path, Map<String, String> headers) {
        String sessionId = headers.getOrDefault("x-session-id", "");
        UserSession session = sessions.get(sessionId);

        if (session == null) {
            sendError(out, 401, "Authentication required");
            return;
        }

        // Extract vault key from path: /vault/{key}
        String vaultKey = path.substring(7); // Remove "/vault/"

        // Validate path - prevent traversal
        if (vaultKey.contains("..") || vaultKey.contains("//")) {
            sendError(out, 400, "Invalid vault key");
            return;
        }

        // Access control: only admin can access secret/ prefix
        // Regular users need sufficient credits for config/ access
        if (vaultKey.startsWith("secret/")) {
            if (!session.isAdmin()) {
                // Non-admin users need credits above threshold to access secrets
                // This is the secondary authorization check
                int availableCredits = session.getAvailableCredits();
                if (availableCredits < 100) { // requires 100 credits, max is 50 + regenerated
                    sendError(out, 403, "Insufficient privileges");
                    return;
                }
            }
        }

        // Check credit availability for any vault access
        if (session.getAvailableCredits() <= 0) {
            sendError(out, 429, "Credit limit reached");
            return;
        }

        session.consumeCredit();

        String value = vaultStore.get(vaultKey);
        if (value == null) {
            sendError(out, 404, "Key not found");
            return;
        }

        sendResponse(out, 200, "{\"key\":\"" + vaultKey + "\",\"value\":\"" + value + "\"}");
    }

    static boolean isValidCredential(String username, String password) {
        if (username == null || password == null) return false;
        if (username.isEmpty() || password.isEmpty()) return false;
        // Simplified auth - in production, compare against hashed passwords
        String expectedHash = getStoredHash(username);
        if (expectedHash == null) return false;
        String inputHash = sha256(password);
        return MessageDigest.isEqual(expectedHash.getBytes(), inputHash.getBytes());
    }

    static String getStoredHash(String username) {
        // Simulated credential store
        Map<String, String> creds = new HashMap<>();
        creds.put("admin", sha256("admin123"));
        creds.put("user1", sha256("password1"));
        creds.put("user2", sha256("password2"));
        return creds.get(username);
    }

    static String sha256(String input) {
        try {
            MessageDigest md = MessageDigest.getInstance("SHA-256");
            byte[] hash = md.digest(input.getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder();
            for (byte b : hash) sb.append(String.format("%02x", b));
            return sb.toString();
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    static String generateSessionId(String username) {
        return sha256(username + System.nanoTime() + Math.random());
    }

    static Map<String, String> parseFormBody(String body) {
        Map<String, String> params = new HashMap<>();
        if (body == null || body.isEmpty()) return params;
        for (String pair : body.split("&")) {
            String[] kv = pair.split("=", 2);
            if (kv.length == 2) {
                params.put(URLDecoder.decode(kv[0], StandardCharsets.UTF_8),
                          URLDecoder.decode(kv[1], StandardCharsets.UTF_8));
            }
        }
        return params;
    }

    static void sendResponse(PrintWriter out, int code, String body) {
        out.println("HTTP/1.1 " + code + " OK");
        out.println("Content-Type: application/json");
        out.println("Content-Length: " + body.length());
        out.println();
        out.print(body);
        out.flush();
    }

    static void sendError(PrintWriter out, int code, String message) {
        String body = "{\"error\":\"" + message + "\"}";
        out.println("HTTP/1.1 " + code + " Error");
        out.println("Content-Type: application/json");
        out.println("Content-Length: " + body.length());
        out.println();
        out.print(body);
        out.flush();
    }
}
